package com.nextrade.engine.settlement; import com.nextrade.common.valueobject.*; import java.math.*; public record FeeSchedule(BigDecimal makerBps,BigDecimal takerBps,Money minimumFee){public Money fee(Money notional,boolean taker){BigDecimal bps=taker?takerBps:makerBps;Money calculated=new Money(notional.amount().multiply(bps).divide(BigDecimal.valueOf(10000),8,RoundingMode.HALF_EVEN),notional.currency());return calculated.compareTo(minimumFee)<0?minimumFee:calculated;}}
